package message

import (
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/free5gc/nas/ie"
)

func TestSecModeCompleteUnmarshalBinary(t *testing.T) {
	t.Parallel()

	testCases := []struct {
		name     string
		input    []byte
		expected Message
	}{
		{
			name: "Case 1",
			input: []byte{
				0x7e, 0x00, 0x5e, // EPD, SecHdr/Spare, Msg Type
				// IMEISV       *ie.MobileId5GS 0x77 TLV-E,      12B, 9.11.3.4
				0x77, 0x00, 0x09,
				0x15, 0x32, 0x54, 0x76, 0x98, 0x00, 0x00, 0x01, 0xf1,
				// NASMsgCntr   *ie.NASMsgCntr  0x71 TLV-E,     4-nB, 9.11.3.33
				0x71, 0x00, 0x58,
				0x7e, 0x00, 0x41, 0x09, 0x00, 0x36, 0x01, 0x02,
				0xf8, 0x39, 0x0f, 0xff, 0x02, 0x02, 0x02, 0x6c,
				0xab, 0x4e, 0x99, 0x52, 0x80, 0x79, 0xfa, 0x7d,
				0x70, 0x1d, 0x0b, 0x5d, 0x9d, 0xdd, 0x79, 0x73,
				0x27, 0xcd, 0xe9, 0x92, 0xf4, 0xa3, 0x13, 0xf5,
				0xe8, 0xc0, 0x6d, 0x04, 0xbf, 0x05, 0x85, 0x3c,
				0x00, 0x7a, 0x95, 0x83, 0x1c, 0x56, 0x5e, 0x66,
				0xf9, 0xeb, 0x14, 0x82, 0x10, 0x01, 0x07, 0x2e,
				0x04, 0x80, 0x20, 0xe0, 0xe0, 0x17, 0x07, 0xe0,
				0xe0, 0xc0, 0x40, 0x00, 0x80, 0x20, 0x50, 0x02,
				0x00, 0x00, 0x2b, 0x01, 0x00, 0x53, 0x01, 0x02,
				// NonimeisvPEI *ie.MobileId5GS 0x78 TLV-E, 7-nB, 9.11.3.4
				0x78, 0x00, 0x07,
				0xf4, 0xfe, 0x00, 0x00, 0x00, 0x00, 0x01,
			},
			expected: &SecModeComplete{
				IMEISV: &ie.MobileId5GS{
					OddEvenIndic: 0,
					TypeOfId:     ie.IdType_5GS_IMEISV,
					IMEISV: [16]uint8{
						1, 2, 3, 4, 5, 6, 7, 8, 9, 0, 0, 0, 0, 1, 0, 1,
					},
				},
				NASMsgCntr: &ie.NASMsgCntr{
					Contents: []byte{
						0x7e, 0x00, 0x41, 0x09, 0x00, 0x36, 0x01, 0x02,
						0xf8, 0x39, 0x0f, 0xff, 0x02, 0x02, 0x02, 0x6c,
						0xab, 0x4e, 0x99, 0x52, 0x80, 0x79, 0xfa, 0x7d,
						0x70, 0x1d, 0x0b, 0x5d, 0x9d, 0xdd, 0x79, 0x73,
						0x27, 0xcd, 0xe9, 0x92, 0xf4, 0xa3, 0x13, 0xf5,
						0xe8, 0xc0, 0x6d, 0x04, 0xbf, 0x05, 0x85, 0x3c,
						0x00, 0x7a, 0x95, 0x83, 0x1c, 0x56, 0x5e, 0x66,
						0xf9, 0xeb, 0x14, 0x82, 0x10, 0x01, 0x07, 0x2e,
						0x04, 0x80, 0x20, 0xe0, 0xe0, 0x17, 0x07, 0xe0,
						0xe0, 0xc0, 0x40, 0x00, 0x80, 0x20, 0x50, 0x02,
						0x00, 0x00, 0x2b, 0x01, 0x00, 0x53, 0x01, 0x02,
					},
				},
				NonimeisvPEI: &ie.MobileId5GS{
					TypeOfId:   ie.IdType_5GS_TMSI,
					AllOneBits: 0x0F,
					AMFSetID:   1016,
					AMFPointer: 0,
					TMSI5G:     [4]byte{0x00, 0x00, 0x00, 0x01},
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			msg := new(SecModeComplete)
			err := msg.UnmarshalBinary(tc.input)
			require.NoError(t, err)
			require.Equal(t, tc.expected, msg)
		})
	}
}

